INSERT INTO `movie` VALUES (1,'Avatar: The Way of Water','2022-12-14',192,'ไซไฟ / ผจญภัย','James Cameron','Sam Worthington, Zoe Saldana','เจคและเนย์ทีรีพาครอบครัวออกเดินทางสู่โลกใต้สมุทรของแพนดอรา เพื่อปกป้องบ้านและคนที่พวกเขารัก','avatar-water.jpg','อวตาร วิถีแห่งสายน้ำ'),(3,'Dune: Part Two','2024-02-28',166,'ไซไฟ / ผจญภัย','Denis Villeneuve',NULL,'พอล อะเทรดีสร่วมเดินทางกับชานีและชาวเฟรเมน ท่ามกลางทะเลทรายอาร์ราคิสและทางเลือกที่จะเปลี่ยนอนาคตของจักรวาล','dune-two.jpg','ดูน ภาคสอง'),(4,'Interstellar','2014-11-05',169,'ไซไฟ / ดราม่า','Christopher Nolan',NULL,'ทีมสำรวจเดินทางผ่านรูหนอนเพื่อค้นหาบ้านใหม่ให้มนุษยชาติ เรื่องราวของเวลา ความหวัง และสายสัมพันธ์ระหว่างพ่อกับลูก','interstellar.jpg','ทะยานดาวกู้โลก'),(5,'Inside Out 2','2024-06-12',96,'แอนิเมชัน / ครอบครัว','Kelsey Mann',NULL,'ไรลีย์ก้าวเข้าสู่วัยรุ่น เมื่ออารมณ์ชุดใหม่เข้ามาในศูนย์บัญชาการ ลั้ลลาและเพื่อน ๆ ต้องเรียนรู้ที่จะเติบโตไปด้วยกัน','inside-out-two.jpg','มหัศจรรย์อารมณ์อลเวง 2'),(6,'Spider-Man: Across the Spider-Verse','2023-05-31',140,'แอนิเมชัน / แอ็กชัน','Joaquim Dos Santos',NULL,'ไมลส์ โมราเลสเดินทางข้ามพหุจักรวาล พบเหล่าสไปเดอร์ฮีโร่ และต้องค้นหาความหมายของการเป็นฮีโร่ในแบบของตัวเอง','spider-verse.jpg','สไปเดอร์แมน ผงาดข้ามจักรวาลแมงมุม'),(7,'Oppenheimer','2023-07-19',180,'ดราม่า / ประวัติศาสตร์','Christopher Nolan',NULL,'เรื่องราวของเจ. โรเบิร์ต ออพเพนไฮเมอร์ นักฟิสิกส์ผู้นำโครงการที่เปลี่ยนโลก พร้อมคำถามถึงผลของการค้นพบทางวิทยาศาสตร์','oppenheimer.jpg','ออพเพนไฮเมอร์'),(8,'Barbie','2023-07-19',114,'คอมเมดี้ / แฟนตาซี','Greta Gerwig',NULL,'บาร์บี้และเคนออกจากบาร์บี้แลนด์สู่โลกจริง การเดินทางที่เต็มไปด้วยสีสันทำให้ทั้งคู่ค้นพบตัวตนและความหมายของความสมบูรณ์แบบ','barbie.jpg','บาร์บี้'),(9,'Top Gun: Maverick','2022-05-25',130,'แอ็กชัน / ดราม่า','Joseph Kosinski',NULL,'มาเวอริคกลับมาฝึกนักบินรุ่นใหม่สำหรับภารกิจที่แทบเป็นไปไม่ได้ และเผชิญหน้ากับอดีตที่ยังคงติดตามเขา','top-gun.jpg','ท็อปกัน มาเวอริค'),(10,'The Wild Robot','2024-09-25',102,'แอนิเมชัน / ครอบครัว','Chris Sanders',NULL,'รอซ หุ่นยนต์ที่ติดอยู่บนเกาะร้าง เรียนรู้ภาษาแห่งธรรมชาติและมิตรภาพ เมื่อเธอกลายเป็นผู้ดูแลลูกห่านตัวหนึ่ง','wild-robot.jpg','หุ่นยนต์ผจญภัยในป่ากว้าง'),(11,'Suzume','2022-11-11',122,'แอนิเมชัน / แฟนตาซี','Makoto Shinkai',NULL,'ซุซุเมะออกเดินทางทั่วญี่ปุ่นเพื่อปิดประตูปริศนาที่นำภัยพิบัติมาสู่โลก และค้นหาคำตอบของความทรงจำในวัยเด็ก','suzume.jpg','การผนึกประตูของซุซุเมะ'),(12,'that',NULL,180,'fik,jk','ืnolan','เจมมี่','ชายคนนึง','uploads/puAljwTjDcxL2kaRRyVLSsWhjZCh9varf68Y5SB1.png','ไทยมหาชน');
/*!40000 ALTER TABLE `movie` ENABLE KEYS */;
